  const restore=async(file:File)=>{try{let bundle:any,assets=new Map<string,Uint8Array>();if(file.name.endsWith('.tar.gz')||file.name.endsWith('.tgz')){const raw=new Uint8Array(await new Response(file.stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer()),files=untar(raw),manifestBytes=files.get('manifest.json');if(!manifestBytes)throw Error('Archive manifest is missing.');const manifest=JSON.parse(new TextDecoder().decode(manifestBytes));if(manifest.format!=='GATEPREP-TAR-GZ'||manifest.schemaVersion>3||manifest.minimumReaderVersion>3)throw Error('Archive version is not supported by this app.');for(const f of manifest.files||[]){const bytes=files.get(f.path);if(!bytes||bytes.length!==f.size||await shaBytes(bytes)!==f.sha256)throw Error('Integrity check failed for '+f.path);}for(const name of manifest.assets||[]){const bytes=files.get(name);if(!bytes)throw Error('Missing asset '+name);assets.set(name,bytes);}const data=files.get('data.json');if(!data)throw Error('Archive data.json is missing.');bundle=inlineAssets(JSON.parse(new TextDecoder().decode(data)),assets);}else{const legacy=JSON.parse(await file.text());if(legacy.contentType!=='gateprep_backup'||!legacy.data)throw Error('Unsupported backup.');bundle={schemaVersion:2,learning:legacy.data};}if(!bundle.learning||!Array.isArray(bundle.learning.questions)||!Array.isArray(bundle.learning.attempts))throw Error('Question or attempt records are invalid.');const knowledge= bundle.knowledge?JSON.parse(bundle.knowledge):[],admissions=bundle.admissions?JSON.parse(bundle.admissions):{},counts={questions:bundle.learning.questions.length,pyqs:bundle.learning.questions.filter((q:any)=>q.isPYQ).length,attempts:bundle.learning.attempts.length,activityEvents:(bundle.learning.events||[]).length,bookmarks:(bundle.learning.bookmarks||[]).length,topicProgress:(bundle.learning.completedTopics||[]).length,notes:knowledge.filter((x:any)=>x.kind==='note').length,abstractions:knowledge.filter((x:any)=>x.kind==='abstraction').length,cheatSheets:knowledge.filter((x:any)=>x.kind==='cheat').length,counselingInstitutes:(admissions.institutes||[]).length,applications:(admissions.applications||[]).length,reminders:(admissions.reminders||[]).length,eligibleCourses:(admissions.courses||[]).length,studyDays:bundle.studyTime?Object.keys(JSON.parse(bundle.studyTime)).length:0},preview='Backup contents — '+counts.questions+' questions ('+counts.pyqs+' PYQs), '+counts.attempts+' attempts, '+counts.activityEvents+' activity events, '+counts.bookmarks+' bookmarks, '+counts.topicProgress+' completed topics; '+counts.notes+' notes, '+counts.abstractions+' abstractions, '+counts.cheatSheets+' cheat sheets; '+counts.counselingInstitutes+' counseling institutes, '+counts.applications+' applications, '+counts.reminders+' reminders, '+counts.eligibleCourses+' eligible courses, '+counts.studyDays+' tracked study days. Knowledge revisions, attachments and study-time history are included. Replace this device data?';if(!confirm(preview+' Export your current data first if needed.'))return;setD(normalise(bundle.learning));if(bundle.knowledge!==undefined)localStorage.setItem('gateprep-knowledge-v1',bundle.knowledge||'[]');if(bundle.taxonomy!==undefined){if(bundle.taxonomy===null)localStorage.removeItem('gateprep-taxonomy-v1');else localStorage.setItem('gateprep-taxonomy-v1',bundle.taxonomy);window.dispatchEvent(new Event('gateprep-taxonomy-updated'));}if(bundle.admissions!==undefined){if(bundle.admissions===null)localStorage.removeItem('gateprep-admissions-v1');else localStorage.setItem('gateprep-admissions-v1',bundle.admissions);}if(bundle.preferences){if(bundle.preferences.theme)localStorage.setItem('gateprep-theme',bundle.preferences.theme);if(bundle.preferences.accent)localStorage.setItem('gateprep-accent',bundle.preferences.accent);}if(bundle.studyTime!==undefined){localStorage.setItem(STUDY_TIME_KEY,bundle.studyTime||'{}');setStudyTime(readStudyTime());}if(bundle.assessments!==undefined)localStorage.setItem('gateprep-assessments-v1',bundle.assessments||'{}');setMessage('Backup verified and restored: learning data, history, course taxonomy, knowledge, admissions and study-time history. Asset checksums passed.');}catch(e){setMessage(e instanceof Error?e.message:'Restore failed.');}};
 const clearHistory=()=>{if(!historyUnlocked||!confirm('Permanently clear all attempt and activity history on this device? This cannot be undone.'))return;change(x=>({...x,attempts:[],events:[]}));setHistoryUnlocked(false);};
 const title={quizzes:'Quizzes',tests:'Test Series',pyqs:'Previous Year Questions',questions:'Questions',subjects:'Subjects & Topics',statistics:'Statistics',history:'History',backup:'Backup & Restore',mistakes:'Mistakes'}[mode];
 const wrong=activeAttempts.filter(a=>!a.correct&&a.selected.length>0),classified=wrong.map(a=>({...a,mistake:a.mistake||'Uncategorized'})),streak=streakCount(studyTime),attemptedCount=activeAttempts.filter(a=>a.selected.length>0||a.correct).length;
 const coverage=coverageCounts(activeQuestions,activeAttempts,subjects,topics);
