  {mode==='backup'&&<><div className="learning-panel"><h2>Backup device</h2><label className="adm-field">Device name<input value={d.settings.device} onChange={e=>change(x=>({...x,settings:{...x.settings,device:e.target.value}}))}/></label><p className="learning-hint">Portable .tar.gz archive with a complete category inventory, schema compatibility metadata, per-file SHA-256 checksums and separate image assets. Includes questions/PYQs and images; attempts, mistakes and activity history; bookmarks and topic progress; notes, abstractions, cheat sheets, their revision history and attachments; counseling institutes and notes, application tracking, reminders, eligible courses; and theme preferences. Earlier JSON backups remain importable (they contain only the data available in that older format).</p><div className="learning-actions"><button className="adm-primary" onClick={()=>void backup()}><Download size={15}/> Export backup</button><label className="adm-secondary"><FileUp size={15}/> Restore .tar.gz / legacy JSON<input hidden type="file" accept=".tar.gz,.tgz,.json,application/gzip,application/json" onChange={e=>{if(e.target.files?.[0])void restore(e.target.files[0]);e.target.value='';e.currentTarget.blur();}}/></label></div>{message&&<p className="learning-hint">{message}</p>}</div><div className="learning-panel"><h2>Backup history</h2>{d.backups.map(b=><div className="history-row" key={b.id}><span><ShieldCheck size={14}/> Exported</span><strong>{b.device} · {b.count} records</strong><time>{new Date(b.at).toLocaleString()} · {b.sha.slice(0,12)}</time></div>)}</div></>}
